FROM (
    SELECT match_id, SUM(runs_scored + extra_runs) AS team_total
    FROM Deliveries
    WHERE match_id IN (
        SELECT match_id FROM Matches WHERE venue LIKE '%धर्मशाला%'
    )
    GROUP BY match_id, inning
);

